def fmt(sec): return f"{int(sec//60)}:{sec%60:05.2f}"
for vid,(plans,tail) in PLANS.items():
    m = json.load(open(os.path.join(root,'public','audio','vo',vid,'timeline.json')))
    meta = META[vid]
    cursor = 0; rows=[]
    for i,seg in enumerate(m['segments']):
        d,g,mn = plans[i]
        voDelay=round(d*FPS); gap=round(g*FPS); vo=int(-(-seg['duration']*FPS//1)); dur=max(round(mn*FPS), voDelay+vo+gap)
        rows.append((i, cursor/FPS, (cursor+dur)/FPS, (cursor+voDelay)/FPS, seg)); cursor+=dur
    total=(cursor+round(tail*FPS))/FPS
    out=os.path.join(repo,'videos',vid); os.makedirs(out,exist_ok=True)
    L=[]
    L.append(f"# {vid} — «{meta['title']}»\n")
    L.append(f"**Тип:** {meta['kind']}  \n**Длительность:** {total:.1f} с · 1080×1920 · 30 fps · H.264 + AAC  \n**Голос:** ElevenLabs `eleven_v3`, {meta['voice']} (русский)  \n**Музыка:** {meta['music']} (процедурная, без лицензионных ограничений)  \n**Субтитры:** {meta['captions']}\n")
    L.append(f"## Концепция\n\n{meta['style']}\n\n**Крючок (первые 2–3 с):** {meta['hook']}\n")
    L.append("## Сценарий и раскадровка\n")
    L.append("| № | Тайминг | Озвучка (дословно) | Визуал |\n|---|---|---|---|")
    for i,a,b,v,seg in rows:
        L.append(f"| {i+1} | {fmt(a)} – {fmt(b)} (голос с {fmt(v)}) | {seg['text']} | {meta['visuals'][i]} |")
    L.append(f"| — | {fmt(cursor/FPS)} – {fmt(total)} | — | Хвост: затухание музыки |\n")
    L.append("## Пословные таймкоды субтитров\n")
    for i,a,b,v,seg in rows:
        words=' '.join(f"{w['text']}[{v+w['start']:.2f}]" for w in seg['words']).replace('lovelink[', 'lovelink.my[')
        L.append(f"**Сцена {i+1}:** {words}\n")
    L.append("## Исходники\n\n* Композиция: `production/remotion/src/videos/Video%s.tsx` (id `%s`)\n* Озвучка и таймкоды: `production/remotion/public/audio/vo/%s/`\n* Музыка: `production/remotion/public/audio/music/%s-music.mp3`\n* Рендер: `cd production/remotion && npm install && node scripts/render.mjs %s`\n" % (vid[-3:], vid, vid, vid, vid))
    L.append("## Проверка фактов\n\nВсе упомянутые функции существуют в коде продукта: шаблоны с категориями «Для кого», редактор фона/видео/причин, публикация со ссылкой, 6-значным паролем и QR-кодом (13 стилей), экран ввода пароля, кабинет «Мои подарки», тарифы Start/Business/Pro, хранение 30 лет, код для редактирования клиенту. Подробности — в `production/STYLE_GUIDE.md` и `production/HANDOFF.md`.\n")
    open(os.path.join(out,'script.md'),'w').write('\n'.join(L))
    print(vid, f"{total:.2f}s")
